pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: prioritize tighter packing (smaller post_residual)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: base cost is high, scaled by current density
    if is_new_bin {
        if fitting_bins_count > 0 {
            // discourage opening a new bin if an existing one is available
            score += 150.0 * (1.0 - progress);
        } else {
            // necessary new bin: reward based on mean_residual to keep new bins efficient
            score -= mean_residual * 0.5;
        }
    } else {
        // Harmonic optimization: 
        // If post_residual is small, it might be a "dead space" trap.
        // We reward fills that leave room for the next_item_size if it exists.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                // Excellent fit: leaves room for the lookahead
                score -= 40.0;
            } else if post_residual > 0 && post_residual < 10 {
                // Poor fit: creates small, unusable sliver
                score += 30.0;
            }
        }

        // Penalty for high open_bins_count to encourage consolidation
        score += (open_bins_count as f64) * 2.0;

        // Harmonic class logic: favor filling bins to specific thresholds
        // 100/3 = 33, 100/2 = 50. Reward residuals near these milestones.
        let m = post_residual % 33;
        if m < 5 {
            score -= 10.0;
        }
    }

    // Adjust for late-stage packing
    if progress > 0.8 {
        score -= (bin_capacity - bin_residual) as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit)
    let mut score = post;

    // Penalty for creating "dead space" (small residuals that are hard to fill)
    // We penalize residuals in the 1-9 range exponentially, as they are likely unusable
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64).powi(3);
    }

    // Lookahead logic: If the next item fits into the current post_residual, 
    // prioritize this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64).powf(1.5);
    }

    // Dynamic adaptation: As the stream progresses, prioritize filling existing bins 
    // more aggressively to minimize fragmentation. 
    // We penalize opening new bins (bin_residual == bin_capacity) increasingly 
    // as we approach the end of the stream.
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 + progress.powi(2));
    }

    // Coupling with mean_residual: If this bin's post_residual is significantly better 
    // than the current average, reward it to consolidate space.
    if post < mean_residual {
        score -= (mean_residual - post).sqrt() * 5.0;
    }

    // Criticality check: If this is the only bin that fits the item, 
    // discourage using a new bin unless the current fit is extremely poor.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

