pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are small but not zero (fragmentation).
    // If post_residual is in (0, 10), it's a "dead zone" for typical item sizes.
    if post_residual > 0 && post_residual < 15 {
        score += 45.0 + (15.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Synergy (Harmonic Coupling): 
    // If we have a next_item, try to leave space that matches it or fits it perfectly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward perfect fits for the next item
            let diff = (post_residual - next_item_size) as f64;
            score -= (25.0 / (1.0 + diff)) + 15.0;
        } else {
            // Penalize if the current placement makes the next item impossible to fit
            score += 20.0;
        }
    }

    // 3. Density Balancing:
    // If we have many open bins, prioritize filling the ones with the lowest residuals (Best Fit).
    // If we have few open bins, prioritize creating space for future items.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score += fill_ratio * 10.0;

    // 4. Thresholding the "New Bin" choice:
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual of current bins is poor
        // or if we are forced to (fitting_bins_count == 0).
        if fitting_bins_count > 0 {
            score += 35.0 + (mean_residual * 0.5);
        } else {
            score -= 10.0; // Forced opening
        }
    }

    // 5. Progression scaling:
    // As the stream nears the end, become more aggressive about minimizing total bins (Best Fit).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize gaps that are too small to fit typical future items.
    // If post_residual is in the range [1, 9], it is essentially "dead space" because min item size is 10.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // 2. Open Bins Pressure: Penalize opening new bins when existing ones have capacity.
    // We heavily penalize the "New Bin" candidate if fitting_bins_count > 0.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 150.0;
    }

    // 3. Lookahead Logic: If the next item is large, avoid leaving a residual that is "just too small" for it.
    if next_item_size > 0 && post_residual < next_item_size {
        // If we can't fit the next item anyway, favor smaller residuals to keep the bin tight.
        // Otherwise, penalize creating a gap that is useless for the next item.
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // 4. Global Density: If we have many open bins, prioritize filling the ones with the lowest residuals
    // to consolidate space (Best-Fit tendency).
    if open_bins_count > 5 {
        score += (bin_residual as f64 - mean_residual) * 0.2;
    }

    // 5. Progression weighting: As the stream nears the end, be more aggressive about closing bins
    // by preferring to fill existing bins over starting new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 100.0;
    }

    score
}
